// GPIO输入配置和读取
// CubeMX: PA0配置为GPIO_Input, Pull: Pull-Up

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    while (1) {
        // 读取PA0按键状态(上拉,按下为低)
        if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
            // 按键按下
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);  // 点亮LED
        } else {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);    // 熄灭LED
        }
    }
}

// 按键控制LED开关
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    uint8_t ledState = 0;

    while (1) {
        if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
            HAL_Delay(20);  // 消抖延时
            if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
                ledState = !ledState;  // 切换状态
                HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, 
                    ledState ? GPIO_PIN_RESET : GPIO_PIN_SET);
                // 等待按键释放
                while (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET);
            }
        }
    }
}

// 延时消抖法
uint8_t readKey(void) {
    if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
        HAL_Delay(20);  // 消抖延时
        if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
            // 确认按下
            while (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET);
            return 1;  // 返回按下
        }
    }
    return 0;  // 未按下
}

// 使用
if (readKey()) {
    HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
}

// stm32f1xx_it.c (CubeMX生成)
