// 中断回调函数
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if (GPIO_Pin == GPIO_PIN_0) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
    }
}

/* 轮询 vs 中断

轮询：
  while(1){
    if(按键) 处理;
    其他任务;
  }
  优点：简单
  缺点：可能错过

中断：
  while(1){ 其他任务; }
  void 回调(){ 处理按键; }
  优点：不错过
  缺点：需消抖

中断中消抖方案：
  设置标志位→主循环延时确认
  或用定时器消抖
*/

// 综合示例：按键计数器
#include "main.h"
volatile int count = 0;

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    while (1) {
        // count在中断中递增
        // 可通过串口显示count
    }
}

void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if (GPIO_Pin == GPIO_PIN_0) {
        count++;
    }
}
